import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

posts = data['records']

# Aggregate by OwnerUserId
user_stats = {}
for post in posts:
    owner_id = post.get('OwnerUserId')
    score = post.get('Score', 0)

    if owner_id is not None:
        if owner_id not in user_stats:
            user_stats[owner_id] = {'post_count': 0, 'total_score': 0}
        user_stats[owner_id]['post_count'] += 1
        user_stats[owner_id]['total_score'] += score

# Convert to list of dicts for dataframe-like output
result = [{'OwnerUserId': uid, 'post_count': stats['post_count'], 'total_score': stats['total_score']} 
          for uid, stats in user_stats.items()]

print(f"Total users with posts: {len(result)}")
print(f"Sample rows:")
for row in result[:10]:
    print(row)
